@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Location {
  + name : string
  + address : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class ChecklistItem {
  + status : string
}

class TaskAssignment {
}

Organizer "1..*" -- "*" Event : organizes
Organizer "0..1" -- "0..*" Event : attends
Event "*" -- "1" EventType : is a kind of
Event "*" -- "1" Location : at
Event "1" -- "*" ChecklistItem : has
Event "1" -- "*" Attendee : invites
Attendee "0..1" -- "0..*" Event : attends
Attendee "1" -- "*" TaskAssignment : performs
Task "1" -- "*" ChecklistItem : defines
Task "1" -- "*" TaskAssignment : is assigned to

@enduml

